-- ==============================================================================
-- AURA E-Commerce: Consolidated Database Re-seeding Script (200 Authentic Products)
-- Complete metadata fields, categories, discounts, flash deal timers in English
-- Product images strictly matched to exact product types (Headphones, Keyboards, Watches, etc.)
-- ==============================================================================

-- 1. Ensure categories exist
INSERT INTO public.categories (id, name, slug, description, image_url, is_featured) VALUES
('a1111111-1111-4111-8111-111111111111', 'Electronics & Audio', 'electronics-audio', 'High performance hardware, flagship headphones, speakers, and smart devices.', 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=600&q=80', true),
('a2222222-2222-4222-8222-222222222222', 'Tech Accessories & Power', 'tech-accessories', 'Premium GaN fast chargers, magnetic power banks, aluminum stands, and cables.', 'https://images.unsplash.com/photo-1586953208448-b95a79798f07?auto=format&fit=crop&w=600&q=80', true),
('a3333333-3333-4333-8333-333333333333', 'Women Skincare & Beauty', 'women-beauty', 'Hydrating hyaluronic serums, botanical body mists, sheet masks, and lip treatments.', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=600&q=80', true),
('a4444444-4444-4444-8444-444444444444', 'Men Grooming & Fragrances', 'men-grooming', 'Refreshing body splashes, beard care oils, energizing scrubs, and deep sea washes.', 'https://images.unsplash.com/photo-1527799820374-dcf8d9d4a388?auto=format&fit=crop&w=600&q=80', true)
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  slug = EXCLUDED.slug,
  description = EXCLUDED.description,
  image_url = EXCLUDED.image_url,
  is_featured = EXCLUDED.is_featured;

-- 2. Clear existing products safely
DELETE FROM public.products;

-- 3. Insert 200 clean authentic non-duplicate products with complete metadata & item-matched images
