  is_flash_deal,
  flash_deal_ends_at,
  images,
  variants,
  rating_avg,
  reviews_count,
  created_at,
  updated_at,
  badge,
  brand,
  sku,
  target_gender,
  origin_country,
  shelf_life,
  key_benefits,
  highlights,
  usage_instructions,
  care_instructions,
